import {validateOriginalWorkspace,sidebarIsHidden} from './original-lab.js';
import {mountDock} from './dock.js';
import {startAuth} from './auth-ui.js';
import {extraToolsHTML,mountExtraTools} from './extra-tools.js';
import {chemicals,elements} from './data.js';
import {balance,parseFormula,molarMass,salt,cations,anions} from './chemistry.js';
import {lessons,practicals,specURL,testCases} from './curriculum.js';
import {esc,fmt,chemText,icon,glassware,date} from './ui.js';
import {defaults,simulate,controlHTML,stageHTML,graphHTML,controls} from './simulations.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let KEY='chemlab.studio.v2';
const NAV=[['bench','Lab bench'],['practicals','Practicals'],['learn','Learn & practise'],['periodic','Periodic table'],['tools','Calculations'],['notebook','Lab notebook']];
let storageOK=true;
function fresh(){return {version:2,vessels:[],sandbox:null,originalLab:null,selected:null,nextVessel:1,notes:[],mastered:[],practised:[],trials:{},params:{},theme:'light',motion:false,score:{correct:0,total:0}};}
function validate(data){
 if(!data||data.version!==2||!Array.isArray(data.vessels)||data.vessels.length>24)throw Error('This is not a Chemlab 2 workspace.');
 const str=(x,n=2000)=>typeof x==='string'&&x.length<=n;
 const num=(x,min,max)=>typeof x==='number'&&Number.isFinite(x)&&x>=min&&x<=max;
 const ids=new Set();
 for(const v of data.vessels){
  if(!num(v.id,1,1e6)||ids.has(v.id)||!['beaker','flask','tube','dish'].includes(v.shape)||!str(v.name,80)||!num(v.capacity,1,500)||!num(v.volume,0,v.capacity)||!num(v.temp,0,1000)||!Array.isArray(v.contents)||v.contents.length>150||!Array.isArray(v.events)||v.events.length>200)throw Error('Invalid vessel data.');ids.add(v.id);
  for(const s of v.contents){const c=s.chem;if(!num(s.n,0,1000)||!c||!str(c.id,100)||!str(c.name,120)||!str(c.formula,80)||!/^#[a-f0-9]{6}$/i.test(c.color)||!['solid','aqueous','liquid','gas'].includes(c.state))throw Error('Invalid chemical data.');const known=chemicals.find(k=>k.id===c.id);if(known){s.chem={...known,state:c.state};}else if(c.id.startsWith('salt:')&&cations[c.cation]&&anions[c.anion]){s.chem={...salt(c.cation,c.anion),state:c.state};}else if(!/^product:[A-Za-z0-9()]+$/.test(c.id))throw Error('Unknown chemical in workspace.');}
  v.events=v.events.map(e=>{if(!str(e.text)||!str(e.time,80))throw Error('Invalid event.');return {time:e.time,text:e.text,type:str(e.type,40)?e.type:'note',kind:str(e.kind,100)?e.kind:undefined,equation:str(e.equation,500)?e.equation:undefined,heat:str(e.heat,50)?e.heat:undefined,limiting:str(e.limiting,200)?e.limiting:undefined};});
  const gas={};for(const [k,n]of Object.entries(v.gas||{})){if(!/^[A-Za-z0-9]{1,20}$/.test(k)||!num(n,0,1000))throw Error('Invalid gas data.');gas[k]=n;}v.gas=gas;
  v.waterVolume=num(v.waterVolume,0,v.volume)?v.waterVolume:v.volume;v.waterConsumed=num(v.waterConsumed,0,1000)?v.waterConsumed:0;v.heated=Boolean(v.heated);if(v.indicator&&!chemicals.some(c=>c.id===v.indicator&&c.category==='indicator'))delete v.indicator;
 }
 if(!Array.isArray(data.notes)||data.notes.length>100||data.notes.some(n=>!str(n.id,80)||!/^[A-Za-z0-9_-]+$/.test(n.id)||!str(n.title,200)||!str(n.body,100000)||!str(n.date,80)))throw Error('Invalid notebook data.');
 data.mastered=Array.isArray(data.mastered)?data.mastered.filter(i=>lessons.some(l=>l.id===i)):[];data.practised=Array.isArray(data.practised)?data.practised.filter(i=>practicals.some(p=>p.id===i)):[];
 const params={};for(const [id,list]of Object.entries(controls)){params[id]=defaults(id);for(const c of list){const v=data.params?.[id]?.[c.key];if(num(v,c.options?0:c.min,c.options?c.options.length-1:c.max))params[id][c.key]=v;}}
 data.params=params;
 const trials={};for(const p of practicals){const t=data.trials?.[p.id];if(Array.isArray(t))trials[p.id]=t.slice(-50).filter(t=>str(t.date,80)&&Array.isArray(t.metrics)&&t.metrics.length<=10&&t.metrics.every(a=>Array.isArray(a)&&a.length===2&&a.every(v=>str(v,1000)))).map(t=>({date:t.date,metrics:t.metrics,params:Object.fromEntries(controls[p.id].map(c=>[c.key,num(t.params?.[c.key],c.options?0:c.min,c.options?c.options.length-1:c.max)?t.params[c.key]:c.value]))}));}data.trials=trials;
 data.nextVessel=Math.max(0,...ids)+1;data.selected=ids.has(data.selected)?data.selected:data.vessels[0]?.id;data.theme=data.theme==='dark'?'dark':'light';data.motion=Boolean(data.motion);data.score={correct:Math.max(0,Math.min(Number(data.score?.correct)||0,100000)),total:Math.max(0,Math.min(Number(data.score?.total)||0,100000))};data.originalLab=data.originalLab?validateOriginalWorkspace(data.originalLab):null;return data;
}
let state;try{const raw=localStorage.getItem(KEY);state=raw?validate(JSON.parse(raw)):fresh();}catch{state=fresh();storageOK=false;}
let activeProfile=null,labFrameProfile=null,labSessionReady=!$('#auth-root')||typeof fetch!=='function',sidebarHidden=sidebarIsHidden(localStorage);
let page='bench',practicalID=null,lessonID=lessons[0].id,noteID=state.notes[0]?.id,filter='',catalogFilter='All',elementQuery='',elementFilter='All',compare=null,quiz=null,quizIndex=0,quizRevealed=false,quizOptions=[],timer=null;
const main=$('#studio-view')||$('#main'),dialog=$('#dialog');
const refreshDock=mountDock();
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;$('#save-status').textContent='Saved on this device';}catch{storageOK=false;$('#save-status').textContent='Storage unavailable · export a backup';}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function applySettings(){document.body.classList.toggle('dark',state.theme==='dark');document.body.classList.toggle('reduce-motion',state.motion);syncSidebar();postOriginalLab('appearance');}
function download(name,content,type='text/plain'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function closeInlinePanel(){dialog.hidden=true;dialog.open=false;const content=$('#dialog-content');if(content)content.innerHTML='';}
function modal(title,html){const host=$('#inline-host');if(host?.appendChild)host.appendChild(dialog);$('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button class="icon-btn" data-act="close" aria-label="Close details">×</button></div><div class="dialog-body">${html}</div>`;dialog.hidden=false;dialog.open=true;}
function formModal(title,body,onSubmit){modal(title,`<form id="modal-form" class="dialog-form">${body}<div class="dialog-actions"><button class="btn" type="button" data-act="close">Cancel</button><button class="btn primary" type="submit">Confirm</button></div></form>`);$('#modal-form').onsubmit=e=>{e.preventDefault();try{onSubmit(new FormData(e.currentTarget));closeInlinePanel();save();render();}catch(e){toast(e.message);}};}
const field=(name,label,value,type='number',extra='')=>`<div class="field"><label for="field-${name}">${esc(label)}</label><input id="field-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;
function heading(title,subtitle,extra='',eyebrow='A LITTLE CURIOSITY GOES A LONG WAY'){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${extra}</div>`;}
function render(){closeInlinePanel();applySettings();document.body.classList.toggle('is-original-bench',page==='bench');const labHost=$('#original-lab-view');if(labHost)labHost.hidden=page!=='bench';main.hidden=page==='bench';const dockLabels={bench:'Lab',practicals:'Practicals',learn:'Learn',periodic:'Elements',tools:'Calculate',notebook:'Notes'};$('#nav').innerHTML=NAV.map(([id,label])=>`<button class="nav-btn ${page===id?'active':''}" data-act="nav" data-id="${id}" aria-label="${label}" title="${label}" ${page===id?'aria-current="page"':''}>${icon(id)}<span class="nav-label">${dockLabels[id]}</span></button>`).join('');refreshDock();$('#crumb').textContent=NAV.find(([id])=>id===page)?.[1]||'Lab bench';
 if(page==='bench')renderBench();if(page==='practicals')practicalID?renderPractical():renderPracticals();if(page==='learn')quiz?renderQuiz():renderLearn();if(page==='periodic')renderPeriodic();if(page==='tools')renderTools();if(page==='notebook')renderNotebook();
 if(!storageOK)$('#save-status').textContent='Export a backup to keep your work';}
function practicalCard(p){const colors={Principles:'#79abd7',Inorganic:'#6fc0b6',Physical:'#ac9dd4',Organic:'#d4b185'};return `<button class="practical-card" style="--card-color:${colors[p.strand]}" data-act="practical" data-id="${p.id}"><div class="category">${esc(p.strand.toUpperCase())} <span class="badge" style="margin-left:8px">${esc(p.ref)}</span></div><div class="card-art">${glassware(p.id==='titration'?'flask':p.id==='analysis'?'tube':'beaker',colors[p.strand],.45,'#edf3f5',p.id==='precipitation')}</div><h3>${esc(p.title)}</h3><p>${esc(p.headline)}</p><div class="card-foot"><span>${state.practised.includes(p.id)?'✓ Explored':'Explore practical'}</span><span class="arrow">↗</span></div></button>`;}
function renderPracticals(){const list=practicals.filter(p=>(catalogFilter==='All'||p.strand===catalogFilter)&&(p.title+' '+p.description+' '+p.ref).toLowerCase().includes(filter.toLowerCase()));main.innerHTML=heading('Find your next “aha”.','18 interactive workspaces, from your first particles to your final practical.',`<span class="pill green">${state.practised.length} / 18 explored</span>`,'THE PRACTICAL COLLECTION')+`<div class="catalog-tools"><div class="chips">${['All','Principles','Inorganic','Physical','Organic'].map(c=>`<button class="chip ${catalogFilter===c?'active':''}" data-act="catalog-filter" data-id="${c}">${c}</button>`).join('')}</div><input id="catalog-search" class="search" placeholder="Search practicals or specification…" aria-label="Search practicals" value="${esc(filter)}"></div><div class="practical-grid" id="practical-grid">${list.map(practicalCard).join('')||'<div class="empty">No matching practicals.</div>'}</div>`;$('#catalog-search').oninput=e=>{filter=e.target.value;const pos=e.target.selectionStart;renderPracticals();$('#catalog-search').focus();$('#catalog-search').setSelectionRange(pos,pos);};}
function simParams(){return state.params[practicalID]||(state.params[practicalID]=defaults(practicalID));}
function renderPractical(){const p=practicals.find(p=>p.id===practicalID),params=simParams(),r=simulate(p.id,params);
 main.innerHTML=heading(p.title,p.description,`<button class="btn subtle" data-act="all-practicals">← All practicals</button>`,`${p.strand.toUpperCase()} · SPEC ${p.ref}`)+`<div class="practical-layout"><div><section class="panel glass"><div class="panel-head"><h2>${esc(p.headline)}</h2><span class="badge">Interactive model</span></div><div class="simulation-body"><div class="sim-stage" id="sim-stage">${stageHTML(p.id,params,r)}</div><div class="control-grid" id="sim-controls">${controlHTML(p.id,params)}</div><div class="sim-actions"><button class="btn primary" data-act="record-trial">＋ Record trial</button><button class="btn" data-act="reset-sim">Reset inputs</button>${r.points?'<button class="btn" data-act="compare">'+(compare?'Clear comparison':'Pin comparison')+'</button>':''}<button class="btn subtle" data-act="sim-csv">Export results ↗</button></div><div class="callout" id="sim-explain" style="margin-top:20px">${esc(r.text)}${r.equation?`<div style="white-space:pre-line;margin-top:10px;font-weight:600">${esc(r.equation)}</div>`:''}</div></div></section><section class="panel glass" style="margin-top:18px"><div class="panel-head"><h2>What the model tells us</h2><span class="muted" style="font-size:10px">Live calculation</span></div><div class="panel-body" id="sim-results"></div></section><section class="panel glass" style="margin-top:18px"><div class="panel-head"><h2>Your trials</h2><button class="btn small" data-act="trial-notebook">Send to notebook ↗</button></div><div class="panel-body" id="trials"></div></section></div><aside><section class="panel glass"><div class="panel-head"><h2>The investigation</h2><span class="badge">${esc(p.ref)}</span></div><div class="panel-body"><ol class="step-list">${p.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="reaction-box">${esc(p.equation)}</div><p class="hint" style="margin-top:16px">Virtual investigation and revision method. Real practicals require a school laboratory and teacher supervision.</p></div></section><section class="panel glass" style="margin-top:18px"><div class="panel-head"><h2>A fair comparison</h2></div><div class="panel-body"><dl class="variables">${p.variables.map((v,i)=>`<div><dt>${['INDEPENDENT','DEPENDENT','CONTROL'][i]}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><details style="margin-top:20px;font-size:11px"><summary>Think it through</summary><p style="margin:12px 0">${esc(p.question)}</p><button class="btn small" data-act="reveal-practical">Reveal answer</button><p id="practical-answer" hidden style="margin-top:12px">${esc(p.answer)}</p></details><button class="btn small" style="width:100%;margin-top:20px" data-act="mark-practical">${state.practised.includes(p.id)?'✓ Explored':'Mark as explored'}</button></div></section></aside></div>`;
 updateSimResults(r);renderTrials();$$('[data-param]').forEach(el=>el.oninput=e=>{const key=e.target.dataset.param;params[key]=Number(e.target.value);const c=controls[p.id].find(c=>c.key===key);if(!c.options)e.target.previousElementSibling.querySelector('output').textContent=fmt(params[key],3)+' '+c.unit;const r=simulate(p.id,params);$('#sim-stage').innerHTML=stageHTML(p.id,params,r);$('#sim-explain').innerHTML=esc(r.text)+(r.equation?`<div style="white-space:pre-line;margin-top:10px;font-weight:600">${esc(r.equation)}</div>`:'');updateSimResults(r);save();});
}
function updateSimResults(r){$('#sim-results').innerHTML=`<div class="table-scroll"><table class="data-table"><tbody>${r.metrics.map(([k,v])=>`<tr><th scope="row">${esc(k)}</th><td>${esc(v)}</td></tr>`).join('')}</tbody></table></div>${graphHTML(r,compare)}${compare?'<p class="hint">Blue: current model · green dashed: pinned comparison</p>':''}`;}
function renderTrials(){const trials=state.trials[practicalID]||[];$('#trials').innerHTML=trials.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Trial</th><th>Recorded</th><th>Result</th></tr></thead><tbody>${trials.map((t,i)=>`<tr><td>${i+1}</td><td>${esc(date(t.date))}</td><td>${t.metrics.slice(0,2).map(([k,v])=>`${esc(k)}: ${esc(v)}`).join('<br>')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="hint">Change an input, then record a trial. Your results stay on this device.</p>';}
function renderLearn(){const l=lessons.find(l=>l.id===lessonID)||lessons[0];main.innerHTML=heading('Understand a little more.','A course-wide revision library, with retrieval practice that remembers your progress.',`<div class="row"><button class="btn" data-act="flashcards">Flashcards</button><button class="btn primary" data-act="start-quiz">Quick practice ↗</button></div>`,'LEARN. CONNECT. REMEMBER.')+`<div class="stats"><div class="metric"><label>TOPICS REVIEWED</label><strong>${state.mastered.length}<small> / ${lessons.length}</small></strong></div><div class="metric"><label>PRACTICALS EXPLORED</label><strong>${state.practised.length}<small> / 18</small></strong></div><div class="metric"><label>PRACTICE ACCURACY</label><strong>${state.score.total?Math.round(state.score.correct/state.score.total*100):0}<small>% · ${state.score.total} answered</small></strong></div></div><div class="lesson-layout"><section class="panel glass"><div class="panel-head"><h2>Your learning map</h2></div><div class="lesson-list">${lessons.map(t=>`<button class="lesson-link ${l.id===t.id?'active':''}" data-act="lesson" data-id="${t.id}"><b>${state.mastered.includes(t.id)?'✓ ':''}${esc(t.title)}</b><small>${esc(t.strand)} · ${esc(t.ref)}</small></button>`).join('')}</div></section><article class="panel glass"><div class="panel-body reading"><span class="badge">${esc(l.strand)} · ${esc(l.ref)}</span><h2>${esc(l.title)}</h2><p>${esc(l.text)}</p><div class="callout"><b>Keep this distinction clear.</b><br>${esc(l.tip)}</div><details><summary>Check your understanding</summary><p>${esc(l.question)}</p><button class="btn small" data-act="reveal-lesson">Reveal answer</button><p id="lesson-answer" hidden>${esc(l.answer)}</p></details><div class="row wrap" style="margin-top:30px"><button class="btn primary" data-act="mastered">${state.mastered.includes(l.id)?'✓ Reviewed · mark unread':'Mark as reviewed'}</button><button class="btn" data-act="next-lesson">Next topic →</button></div><p class="hint" style="margin-top:30px">Original study notes, organised around Edexcel 4CH1. Topic summaries support revision; use the <a href="${specURL}" target="_blank" rel="noopener">official specification</a> for the full learning statements.</p></div></article></div>`;}
function shuffle(a){return [...a].sort(()=>Math.random()-.5);}
function startQuiz(mode){quiz={mode,items:shuffle(lessons).slice(0,mode==='flash'?lessons.length:10),correct:0,answers:[]};quizIndex=0;quizRevealed=false;setOptions();render();}
function setOptions(){if(!quiz||quizIndex>=quiz.items.length)return;const l=quiz.items[quizIndex];quizOptions=shuffle([l.answer,...shuffle(lessons.filter(x=>x.id!==l.id)).slice(0,3).map(x=>x.answer)]);}
function renderQuiz(){if(quizIndex>=quiz.items.length){main.innerHTML=heading('A little progress, every time.','Your practice session is complete. Every answer is a useful next step.')+`<section class="panel glass"><div class="panel-body reading"><h2>${quiz.mode==='flash'?'Deck complete.':quiz.correct+' / '+quiz.items.length+' correct.'}</h2><p>${quiz.mode==='flash'?'You worked through the topic deck.':'Revisit any missed concepts below.'}</p>${quiz.answers.filter(a=>!a.correct).map(a=>`<div class="callout" style="margin:10px 0"><b>${esc(a.lesson.question)}</b><br>${esc(a.lesson.answer)}</div>`).join('')}<button class="btn primary" data-act="end-quiz">Back to learning</button></div></section>`;return;}
 const l=quiz.items[quizIndex];main.innerHTML=heading(quiz.mode==='flash'?'A thought to turn over.':'Put your understanding to work.',`${quiz.mode==='flash'?'Flashcard':'Question'} ${quizIndex+1} of ${quiz.items.length}`,`<button class="btn subtle" data-act="end-quiz">Finish session</button>`,'RETRIEVAL PRACTICE')+`<section class="panel glass"><div class="panel-body reading" style="margin:auto;padding:35px;max-width:850px"><div class="progress-track"><i style="width:${quizIndex/quiz.items.length*100}%"></i></div><p class="muted" style="font-size:11px">${esc(l.strand)} · ${esc(l.title)}</p><h2>${esc(l.question)}</h2>${quiz.mode==='flash'?`<div class="callout" ${quizRevealed?'':'hidden'}>${esc(l.answer)}</div><div class="row" style="margin-top:25px">${quizRevealed?'<button class="btn primary" data-act="next-question">Next card →</button>':'<button class="btn primary" data-act="flip-card">Turn card ↻</button>'}</div>`:`<div class="quiz-options">${quizOptions.map((o,i)=>`<button class="quiz-option ${quizRevealed&&o===l.answer?'correct':quizRevealed&&quiz.answers.at(-1)?.choice===i?'wrong':''}" data-act="quiz-answer" data-id="${i}" ${quizRevealed?'disabled':''}>${esc(o)}</button>`).join('')}</div>${quizRevealed?`<div class="callout">${esc(l.tip)}</div><button class="btn primary" style="margin-top:20px" data-act="next-question">Next question →</button>`:''}`}</div></section>`;}
function elementType(e){if(e.n>=57&&e.n<=71)return 'Lanthanides';if(e.n>=89&&e.n<=103)return 'Actinides';if(e.g===18)return 'Noble gases';if(e.g===17)return 'Halogens';if(e.g===1&&e.n!==1)return 'Alkali metals';if(e.g===2)return 'Alkaline earth';if([5,14,32,33,51,52].includes(e.n))return 'Metalloids';if([1,6,7,8,15,16,34].includes(e.n))return 'Non-metals';if(e.g>=3&&e.g<=12)return 'Transition metals';return 'Other metals';}
const elementColors={'Alkali metals':'#d6a26d','Alkaline earth':'#cab77a','Transition metals':'#8ea7d3','Other metals':'#9bbac7','Metalloids':'#85b5a4','Non-metals':'#70b8be','Halogens':'#b695be','Noble gases':'#a69acb','Lanthanides':'#b6a5cb','Actinides':'#c8a2b7'};
function renderPeriodic(){main.innerHTML=heading('Meet the building blocks.','All 118 elements. One connected story.',`<span class="pill">Tap an element to explore</span>`,'THE PERIODIC TABLE')+`<section class="panel glass"><div class="panel-body"><div class="catalog-tools"><input id="element-search" class="search" aria-label="Find an element" value="${esc(elementQuery)}" placeholder="Find by name, symbol or number…"><select id="element-filter" aria-label="Filter element families"><option>All</option>${Object.keys(elementColors).map(t=>`<option ${elementFilter===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="periodic-scroll"><div class="periodic" id="periodic-grid"></div></div><div class="row wrap" style="margin-top:22px">${Object.entries(elementColors).map(([k,c])=>`<span class="pill" style="font-size:9px"><span class="dot" style="--chem:${c};margin:0"></span>${k}</span>`).join('')}</div><p class="hint" style="margin-top:20px">Decimal values are rounded relative atomic masses. For elements without a standard atomic weight, a representative isotope mass number is shown. In exam calculations, use the relative atomic masses supplied in the question.</p></div></section>`;renderElements();$('#element-search').oninput=e=>{elementQuery=e.target.value;renderElements();};$('#element-filter').onchange=e=>{elementFilter=e.target.value;renderElements();};}
function renderElements(){$('#periodic-grid').innerHTML=elements.map(e=>{let row=e.p,col=e.g;if(e.n>=57&&e.n<=71){row=9;col=e.n-54;}if(e.n>=89&&e.n<=103){row=10;col=e.n-86;}const q=elementQuery.toLowerCase(),dim=(elementFilter!=='All'&&elementType(e)!==elementFilter)||!(`${e.n} ${e.s} ${e.nm}`.toLowerCase().includes(q));return `<button class="element ${dim?'dim':''}" style="grid-column:${col};grid-row:${row};--el:${elementColors[elementType(e)]}" data-act="element" data-id="${e.n}" aria-label="${e.n} ${esc(e.nm)}"><span>${e.n}</span><b>${e.s}</b><small>${esc(e.nm)}</small></button>`;}).join('');}
function renderTools(){main.innerHTML=heading('Let the numbers make sense.','Show your working, check your units, and connect the calculation to the chemistry.','','A SMALL TOOLKIT FOR BIG QUESTIONS')+`<div class="tool-grid"><section class="panel glass"><div class="panel-head"><h2>Equation balancer</h2><span class="badge">Conserves atoms</span></div><div class="panel-body"><form id="balance-form" class="tool-form"><div class="field"><label for="equation">Reactants → products</label><input id="equation" required value="Fe + O2 -> Fe2O3" placeholder="H2 + O2 -> H2O"></div><button class="btn primary">Balance equation</button></form><p class="tools-help">Use neutral formulae, + and → or ->. Round brackets and hydrates with · are supported. Ionic charge balancing is outside this tool.</p><div id="balance-result" aria-live="polite"></div></div></section><section class="panel glass"><div class="panel-head"><h2>Formula mass & composition</h2></div><div class="panel-body"><form id="mass-form" class="tool-form"><div class="field"><label for="formula">Chemical formula</label><input id="formula" value="CuSO4·5H2O" required></div><button class="btn primary">Calculate molar mass</button></form><div id="mass-result" aria-live="polite"></div></div></section><section class="panel glass"><div class="panel-head"><h2>Quantities calculator</h2></div><div class="panel-body"><form id="quantity-form" class="tool-form"><div class="field"><label for="quantity-mode">Calculation</label><select id="quantity-mode"><option value="moles">Moles: mass ÷ molar mass</option><option value="concentration">Concentration: moles ÷ volume (dm³)</option><option value="gas">Gas volume at RTP (dm³)</option><option value="yield">Percentage yield</option><option value="energy">Q = mass × 4.18 × ΔT</option><option value="enthalpy">ΔH = −Q ÷ n (kJ/mol)</option><option value="rf">Chromatography Rf</option><option value="empirical">Empirical ratio from two masses</option></select></div><div class="field"><label id="qa-label" for="qa">Mass / g</label><input id="qa" type="number" value="4.8" step="any" required></div><div class="field" id="qb-wrap"><label id="qb-label" for="qb">Molar mass / g mol⁻¹</label><input id="qb" type="number" value="24" step="any" required></div><div id="empirical-extra" hidden><div class="row">${field('arA','Ar of first element',24,'number','step="any"')}${field('arB','Ar of second element',16,'number','step="any"')}</div></div><button class="btn primary">Show working</button></form><div id="quantity-result" aria-live="polite"></div></div></section><section class="panel glass"><div class="panel-head"><h2>Bond-energy calculation</h2><span class="badge">3.7C</span></div><div class="panel-body"><p class="hint" style="margin-bottom:18px">Enter total energy for all bonds broken and all bonds formed, using the balanced equation. Example: H₂ + Cl₂ → 2HCl, 436 + 243 broken and 2 × 431 formed.</p><form id="bond-form" class="tool-form">${field('broken','Total bonds broken / kJ mol⁻¹',679,'number','step="any" min="0" required')}${field('formed','Total bonds formed / kJ mol⁻¹',862,'number','step="any" min="0" required')}<button class="btn primary">Calculate ΔH</button></form><div id="bond-result" aria-live="polite"></div></div></section>${extraToolsHTML()}</div>`;
 mountExtraTools(main);
 const result=(target,fn)=>{try{$(target).innerHTML=`<div class="result">${fn()}</div>`;}catch(e){$(target).innerHTML=`<div class="result error">${esc(e.message)}</div>`;}};
 $('#balance-form').onsubmit=e=>{e.preventDefault();result('#balance-result',()=>{const parts=$('#equation').value.trim().split(/->|→|=/);if(parts.length!==2)throw Error('Use one arrow between reactants and products.');const sides=parts.map(s=>s.split('+').map(s=>s.trim().replace(/^\d+(?=[A-Z(])/,'')).filter(Boolean));if(sides.some(s=>!s.length)||sides.flat().length>12)throw Error('Enter 1–12 valid species.');sides.flat().forEach(f=>molarMass(f,elements));const b=balance(...sides);return `<b>${chemText(b.text)}</b><br><span class="hint">Coefficients: ${b.coefficients.join(' : ')}. Each element is conserved.</span>`;});};
 $('#mass-form').onsubmit=e=>{e.preventDefault();result('#mass-result',()=>{const formula=$('#formula').value.trim(),mass=molarMass(formula,elements),atoms=parseFormula(formula);return `${chemText(formula)}<br><b>${fmt(mass,3)} g/mol</b><br>${Object.entries(atoms).map(([s,n])=>s+': '+fmt(n*Number(elements.find(e=>e.s===s).m.replace(/[()]/g,''))/mass*100)+'% by mass').join(' · ')}`;});};
 const labels={moles:['Mass / g','Molar mass / g mol⁻¹'],concentration:['Amount / mol','Solution volume / cm³'],gas:['Amount of gas / mol',''],yield:['Actual yield / g','Theoretical yield / g'],energy:['Mass of water / g','Temperature change / °C'],enthalpy:['Heat gained by surroundings Q / J','Amount reacted / mol'],rf:['Spot distance from baseline / cm','Solvent-front distance / cm'],empirical:['First element mass / g','Second element mass / g']};
 $('#quantity-mode').onchange=e=>{const k=e.target.value;$('#qa-label').textContent=labels[k][0];$('#qb-label').textContent=labels[k][1];$('#qb-wrap').hidden=!labels[k][1];$('#empirical-extra').hidden=k!=='empirical';$('#quantity-result').innerHTML='';};
 $('#quantity-form').onsubmit=e=>{e.preventDefault();result('#quantity-result',()=>{const k=$('#quantity-mode').value,a=Number($('#qa').value),b=Number($('#qb').value);if(!Number.isFinite(a)||!Number.isFinite(b)||(!['energy','enthalpy'].includes(k)&&a<0)||k!=='gas'&&b===0)throw Error('Use finite, physically valid values; the divisor must be positive.');if(!['gas','energy'].includes(k)&&b<=0)throw Error('The divisor must be positive.');
  if(k==='moles')return `n = ${a} ÷ ${b} = <b>${fmt(a/b,6)} mol</b>`;if(k==='concentration')return `c = ${a} ÷ (${b} ÷ 1000) = <b>${fmt(a/(b/1000),6)} mol/dm³</b>`;if(k==='gas')return `V = ${a} × 24 = <b>${fmt(a*24,6)} dm³ at RTP</b>`;if(k==='yield')return `yield = ${a} ÷ ${b} × 100 = <b>${fmt(a/b*100)}%</b>${a>b?'<p class="hint">Above 100% suggests a wet/impure product or measurement error.</p>':''}`;if(k==='energy'){if(a<=0)throw Error('Mass must be positive.');return `Q = ${a} × 4.18 × ${b} = <b>${fmt(a*4.18*b)} J</b>`;}if(k==='enthalpy')return `ΔH = −${a} ÷ ${b} ÷ 1000 = <b>${fmt(-a/b/1000,4)} kJ/mol</b>`;if(k==='rf'){if(a>b)throw Error('A spot cannot travel beyond the solvent front in this model.');return `Rf = ${a} ÷ ${b} = <b>${fmt(a/b,4)}</b> (no unit)`;}if(k==='empirical'){const arA=Number($('#field-arA').value),arB=Number($('#field-arB').value);if(arA<=0||arB<=0||a<=0||b<=0)throw Error('Masses and relative atomic masses must be positive.');const n1=a/arA,n2=b/arB,min=Math.min(n1,n2);return `Moles: ${fmt(n1,5)} and ${fmt(n2,5)}<br>Ratio: <b>${fmt(n1/min,3)} : ${fmt(n2/min,3)}</b><br>Multiply fractional ratios to get the simplest whole numbers; use your experimental uncertainty.`;}});};
 $('#bond-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);result('#bond-result',()=>{const b=Number(f.get('broken')),m=Number(f.get('formed'));if(!Number.isFinite(b)||!Number.isFinite(m)||b<0||m<0)throw Error('Enter positive bond-energy totals.');return `ΔH = ${b} − ${m} = <b>${fmt(b-m)} kJ/mol</b><br>${b<m?'Exothermic':b>m?'Endothermic':'No net enthalpy change in this estimate'}`;});};
}
function addNote(title,body){const n={id:'note-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),title,body,date:new Date().toISOString()};state.notes.unshift(n);noteID=n.id;if(state.notes.length>100)state.notes.pop();save();toast('Added to your lab notebook.');}
function renderNotebook(){const n=state.notes.find(n=>n.id===noteID)||state.notes[0];noteID=n?.id;main.innerHTML=heading('Keep the thought.','Your observations, questions and “I wonder…” moments, saved together.',`<div class="row"><button class="btn" data-act="export-notes">Export notes ↗</button><button class="btn primary" data-act="new-note">＋ New entry</button></div>`,'THE LAB NOTEBOOK')+`<div class="notebook-layout"><section class="panel glass"><div class="panel-head"><h2>Entries</h2><span class="badge">${state.notes.length}</span></div><div class="panel-body" style="padding:10px">${state.notes.map(t=>`<button class="notebook-entry ${t.id===noteID?'active':''}" data-act="note" data-id="${t.id}"><h3>${esc(t.title||'Untitled entry')}</h3><small>${date(t.date)}</small></button>`).join('')||'<div class="empty">A clean page for a curious mind.</div>'}</div></section><section class="panel glass"><div class="panel-head"><h2>${n?'Your observation':'Start a new entry'}</h2>${n?'<button class="btn small danger" data-act="delete-note">Delete entry</button>':''}</div><div class="panel-body notebook-editor">${n?`<label class="mini-label" for="note-title">ENTRY TITLE</label><input id="note-title" value="${esc(n.title)}" maxlength="200"><div class="hint">${date(n.date)} · autosaved locally</div><label class="mini-label" style="display:block" for="note-body">METHOD, RESULTS & REFLECTIONS</label><textarea id="note-body" maxlength="100000" placeholder="What did you change? What did you observe? What does it tell you?">${esc(n.body)}</textarea><div class="row"><button class="btn small" data-act="export-entry">Export this entry</button><button class="btn small" data-act="print">Print</button></div>`:'<div class="empty">Record a practical, save a bench observation, or create a new note.</div>'}</div></section></div>`;if(n){$('#note-title').oninput=e=>{n.title=e.target.value;save();};$('#note-body').oninput=e=>{n.body=e.target.value;save();};}}
function exportTrials(){const r=simulate(practicalID,simParams()),trials=state.trials[practicalID]||[],csvCell=v=>'"'+String(v).replace(/"/g,'""')+'"',rows=[['Trial','Date','Quantity','Value']];trials.forEach((t,i)=>t.metrics.forEach(([k,v])=>rows.push([i+1,t.date,k,v])));if(!trials.length)r.metrics.forEach(([k,v])=>rows.push(['Live model',new Date().toISOString(),k,v]));if(r.points){rows.push([],['Current curve',r.xLabel,r.yLabel]);r.points.forEach(([x,y])=>rows.push(['',x,y]));}download('chemlab-'+practicalID+'.csv',rows.map(row=>row.map(csvCell).join(',')).join('\r\n'),'text/csv');}
const actions={
 nav:id=>{page=id;practicalID=null;quiz=null;location.hash=id;render();},close:()=>closeInlinePanel(),'toggle-sidebar':()=>{sidebarHidden=!sidebarHidden;try{localStorage.setItem('chemlab.sidebar.hidden',sidebarHidden?'1':'0');}catch{}syncSidebar();},
 export:()=>{captureOriginalLab();download('chemlab-workspace.json',JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),'application/json');},
 import:()=>$('#import-file').click(),
 theme:()=>{state.theme=state.theme==='light'?'dark':'light';save();applySettings();},
 settings:()=>modal('Your workspace',`<p>Your experiments, notes and progress are stored in this browser on this device. Export a workspace backup to move them or keep a separate copy.</p><div class="row wrap"><button class="btn" data-act="export">Export workspace</button><button class="btn" data-act="import">Import workspace</button><a class="btn" href="Chemlab.html" download="Chemlab.html">Download offline app</a></div><label class="check"><input id="motion" type="checkbox" ${state.motion?'checked':''}>Reduce animation</label><p class="hint">The system’s reduced-motion preference is also respected.</p>`),
 practical:id=>{practicalID=id;page='practicals';compare=null;location.hash='practicals/'+id;render();},'all-practicals':()=>{practicalID=null;compare=null;location.hash='practicals';render();},'catalog-filter':id=>{catalogFilter=id;render();},
 'record-trial':()=>{const p=practicals.find(p=>p.id===practicalID),r=simulate(p.id,simParams());const t=state.trials[p.id]||(state.trials[p.id]=[]);t.push({date:new Date().toISOString(),metrics:r.metrics,params:{...simParams()}});if(t.length>50)t.shift();if(!state.practised.includes(p.id))state.practised.push(p.id);save();renderTrials();toast('Trial '+t.length+' recorded.');},
 'reset-sim':()=>{state.params[practicalID]=defaults(practicalID);save();render();},compare:()=>{compare=compare?null:simulate(practicalID,simParams());render();},'sim-csv':exportTrials,
 'trial-notebook':()=>{const p=practicals.find(p=>p.id===practicalID),t=state.trials[p.id]||[];if(!t.length){toast('Record a trial first.');return;}addNote(p.title+' · practical report',`${p.title}\nSpecification: ${p.ref}\n\nMethod:\n${p.steps.map((s,i)=>`${i+1}. ${s}`).join('\n')}\n\nResults:\n${t.map((t,i)=>`Trial ${i+1} (${date(t.date)})\n${t.params?Object.entries(t.params).map(([k,v])=>`${k}: ${v}`).join('; ')+'\n':''}${t.metrics.map(([k,v])=>`${k}: ${v}`).join('\n')}`).join('\n\n')}\n\nModel assumptions:\n${simulate(p.id,simParams()).text}\n\nConclusion:\n\nEvaluation:\n`);},
 'reveal-practical':()=>{$('#practical-answer').hidden=false;},'mark-practical':()=>{if(!state.practised.includes(practicalID))state.practised.push(practicalID);save();render();},
 lesson:id=>{lessonID=id;render();},'reveal-lesson':()=>{$('#lesson-answer').hidden=false;},mastered:()=>{state.mastered=state.mastered.includes(lessonID)?state.mastered.filter(id=>id!==lessonID):[...state.mastered,lessonID];save();render();},'next-lesson':()=>{lessonID=lessons[(lessons.findIndex(l=>l.id===lessonID)+1)%lessons.length].id;render();},
 'start-quiz':()=>startQuiz('quiz'),flashcards:()=>startQuiz('flash'),'end-quiz':()=>{quiz=null;render();},'flip-card':()=>{quizRevealed=true;render();},
 'quiz-answer':id=>{if(quizRevealed)return;const l=quiz.items[quizIndex],i=Number(id),correct=quizOptions[i]===l.answer;quizRevealed=true;quiz.answers.push({lesson:l,choice:i,correct});quiz.correct+=Number(correct);state.score.correct+=Number(correct);state.score.total++;save();render();},
 'next-question':()=>{quizIndex++;quizRevealed=false;setOptions();render();},
 element:id=>{const e=elements.find(e=>e.n===Number(id)),config=e.n<=20?(e.n<=2?[e.n]:e.n<=10?[2,e.n-2]:e.n<=18?[2,8,e.n-10]:[2,8,8,e.n-18]).join(', '):'First-20 shell model not applied';modal(e.nm,`<div class="row" style="align-items:start"><div style="font-size:65px;line-height:1;padding:10px 20px;background:${elementColors[elementType(e)]}30;border-radius:20px">${e.s}</div><div><span class="badge">${elementType(e)}</span><h2 style="margin-top:12px">${e.nm}</h2><p>Atomic number ${e.n} · period ${e.p}</p></div></div><div class="metric-pair" style="margin-top:20px"><div class="metric"><label>RELATIVE ATOMIC MASS / ISOTOPE</label><strong>${e.m}</strong></div><div class="metric"><label>PROTONS</label><strong>${e.n}</strong></div></div><p><b>Electron shells:</b> ${config}</p><p class="hint">A neutral atom has ${e.n} electrons. Neutron count requires a specific isotope mass number. Relative atomic mass is not generally a mass number.</p>`);},
 'new-note':()=>{addNote('A new observation','Question / aim:\n\nPrediction:\n\nMethod:\n\nResults:\n\nConclusion:\n\nEvaluation:\n');render();},note:id=>{noteID=id;render();},
 'delete-note':()=>formModal('Delete this notebook entry',`<p>Remove “${esc(state.notes.find(n=>n.id===noteID)?.title)}” from this device? Export it first if you need a copy.</p>`,()=>{state.notes=state.notes.filter(n=>n.id!==noteID);noteID=state.notes[0]?.id;}),
 'export-notes':()=>download('chemlab-notebook.txt',state.notes.map(n=>n.title+'\n'+date(n.date)+'\n\n'+n.body).join('\n\n'+'─'.repeat(50)+'\n\n')),
 'export-entry':()=>{const n=state.notes.find(n=>n.id===noteID);download('chemlab-entry.txt',n.title+'\n'+n.body);},print:()=>window.print(),
 about:()=>modal('ChemLab · your chemistry studio',`<p>The laboratory uses the original JavaScript, 119-chemical catalogue and Python reaction engine from your supplied Chemlab-main.zip, with a new responsive layout and glass controls. Its original reaction rules and simplifications apply.</p><p>Laboratory work and study progress save in this browser per username; export a backup to move them.</p><p>Use the top-left button to hide the navigation dock. Liquid-glass styling is applied separately from the chemistry code.</p>`),
 help:()=>modal('Your laboratory',`<p>Open the cupboard with the first button in the lab header. Use Apparatus to place glassware, a burner, burette or supporting apparatus. Drag chemicals into a vessel and use the pouring controls.</p><p>The lab toolbar saves or opens an original workspace. Its notes can be sent to the Studio notebook. Export workspace includes both study progress and the original lab.</p><p>Drag the grip at the left of the navigation dock to move it. Double-click the grip to return it to the bottom centre. With the grip focused, use arrow keys to move it, or Home to reset. The top-left navigation button hides the dock to give the bench more room.</p><p>On smaller screens, the cupboard and reaction information open over the bench. The original chemistry bench requires the local Python server or Render.</p>`)
};
document.addEventListener('click',e=>{const btn=e.target.closest('[data-act]');if(btn&&!btn.disabled){try{actions[btn.dataset.act]?.(btn.dataset.id);}catch(e){toast(e.message);}}});
document.addEventListener('change',e=>{if(e.target.id==='motion'){state.motion=e.target.checked;save();applySettings();}});
$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1500000)throw Error('Workspace files must be under 1.5 MB.');const candidate=validate(JSON.parse(await file.text()));formModal('Restore this workspace',`<p>Replace this device’s workspace with ${candidate.vessels.length} vessels and ${candidate.notes.length} notebook entries? Export the current workspace first if you want to keep it.</p>`,()=>{state=candidate;labFrameProfile=null;page='bench';save();});}catch(e){toast('Could not import: '+e.message);}e.target.value='';};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&dialog.open){e.preventDefault();closeInlinePanel();main?.focus();return;}if(e.key==='?'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();actions.help();}});
function route(){const [p,id]=location.hash.slice(1).split('/');if(NAV.some(([n])=>n===p)){page=p;practicalID=p==='practicals'&&practicals.some(x=>x.id===id)?id:null;quiz=null;render();}}
window.addEventListener('hashchange',route);applySettings();route();render();

startAuth({onUser:(user,options={})=>{
 if(options.error){toast(options.error);return;}
 if(options.logout){captureOriginalLab();save();labSessionReady=false;labFrameProfile=null;const host=$('#original-lab-view');if(host)host.innerHTML='';activeProfile=null;KEY='chemlab.studio.v2';state=fresh();page='bench';render();}
 else if(user&&activeProfile!==user.username.toLowerCase()){
  labSessionReady=true;labFrameProfile=null;
  activeProfile=user.username.toLowerCase();KEY='chemlab.studio.v2:'+activeProfile;
  try{const saved=localStorage.getItem(KEY);state=saved?validate(JSON.parse(saved)):fresh();}catch{state=fresh();toast('The saved workspace could not be restored. Import a backup if needed.');}
  noteID=state.notes[0]?.id;page='bench';render();
 }
 if(options.offline){labSessionReady=true;render();}
 const button=$('#account-button');if(button){button.textContent=user?'Sign out':'Sign in';button.title=user?'Signed in as '+user.username:'Chemlab account';}
 const avatar=$('.avatar');if(avatar){avatar.textContent=user?user.username[0].toUpperCase():'C';avatar.title=user?user.username:'Offline learner';}
}});

function postOriginalLab(type,extra={}){const frame=$('#original-lab-frame');frame?.contentWindow?.postMessage({source:'chemlab-studio',type,profile:activeProfile||'guest',theme:state.theme,motion:state.motion,...extra},location.origin);}
function captureOriginalLab(){const frame=$('#original-lab-frame');try{if(frame?.contentWindow?.serializeWorkspace){state.originalLab=validateOriginalWorkspace(frame.contentWindow.serializeWorkspace());save();}}catch{toast('Export a backup from the lab toolbar if this workspace could not be captured.');}}
function syncSidebar(){document.body.classList.toggle('sidebar-hidden',sidebarHidden);const dock=$('#main-sidebar');if(dock)dock.inert=sidebarHidden;const button=$('#sidebar-toggle');if(button){button.setAttribute('aria-expanded',String(!sidebarHidden));button.setAttribute('aria-label',sidebarHidden?'Show navigation dock':'Hide navigation dock');button.title=sidebarHidden?'Show navigation dock':'Hide navigation dock';}}
function renderBench(){
 const host=$('#original-lab-view')||main;
 if(!labSessionReady){host.innerHTML='<div class="original-lab-notice"><h1>Original chemistry lab</h1><p>Sign in to open your laboratory.</p></div>';return;}
 if(location.protocol==='file:'){host.innerHTML='<section class="panel glass original-lab-notice"><h1>Original chemistry lab</h1><p>The original lab uses its Python reaction engine. Run <code>python app.py</code>, then open <a href="http://127.0.0.1:5050">http://127.0.0.1:5050</a>, or use your Render website. Practicals, revision, calculations and the notebook remain available offline.</p></section>';return;}
 if(labFrameProfile!==KEY||!$('#original-lab-frame')){host.innerHTML='<iframe id="original-lab-frame" class="original-lab-frame" src="/original-lab/" title="Original ChemLab chemistry laboratory" allow="fullscreen" referrerpolicy="same-origin"></iframe>';labFrameProfile=KEY;}
}
window.addEventListener('message',event=>{
 const frame=$('#original-lab-frame'),data=event.data;
 if(!labSessionReady||!frame?.contentWindow||event.source!==frame.contentWindow||event.origin!==location.origin||data?.source!=='chemlab-original')return;
 if(data.type==='ready'){postOriginalLab('init',{workspace:state.originalLab});return;}
 if(data.profile!==(activeProfile||'guest'))return;
 if(data.type==='workspace')try{state.originalLab=validateOriginalWorkspace(data.workspace);save();}catch{toast('The laboratory returned an invalid save. Export a backup from its toolbar.');}
 if(data.type==='theme'){state.theme=data.theme==='dark'?'dark':'light';save();applySettings();}
 if(data.type==='note'&&typeof data.text==='string')addNote('Original lab notes',data.text.slice(0,100000));
 if(data.type==='error'&&typeof data.message==='string')toast(data.message.slice(0,300));
});
